case object Admin extends Role
case object Editor extends Role
case object Viewer extends Role

case class User(id: String, username: String, passwordHash: String, role: Role)

// Dynamic configuration store - supports nested property paths
class ConfigStore {
  private val store: mutable.Map[String, Any] = mutable.Map(
    "app.name" -> "AcmePortal",
    "app.version" -> "2.1.0",
    "security.maxLoginAttempts" -> 5,
    "security.sessionTimeout" -> 3600,
    "security.roleHierarchy" -> mutable.Map(
      "admin" -> mutable.Map("canEscalate" -> true, "level" -> 100),
      "editor" -> mutable.Map("canEscalate" -> false, "level" -> 50),
      "viewer" -> mutable.Map("canEscalate" -> false, "level" -> 10)
    )
  )

  def get(path: String): Option[Any] = {
    val segments = path.split("\\.")
    navigate(store, segments.toList)
  }

  def set(path: String, value: Any): Unit = {
    val segments = path.split("\\.")
    setNested(store, segments.toList, value)
  }

  private def navigate(current: mutable.Map[String, Any], segments: List[String]): Option[Any] = {
    segments match {
      case Nil => None
      case head :: Nil => current.get(head)
      case head :: tail =>
        current.get(head) match {
          case Some(nested: mutable.Map[String, Any] @unchecked) => navigate(nested, tail)
          case _ => None
        }
    }
  }

  private def setNested(current: mutable.Map[String, Any], segments: List[String], value: Any): Unit = {
    segments match {
      case Nil => ()
      case head :: Nil => current(head) = value
      case head :: tail =>
        val nested = current.getOrElseUpdate(head, mutable.Map[String, Any]())
        nested match {
          case m: mutable.Map[String, Any] @unchecked => setNested(m, tail, value)
          case _ => ()
        }
    }
  }
}

// Access control service
class AccessControl(configStore: ConfigStore) {

  def canPerformAction(user: User, action: String): Boolean = {
    val roleName = user.role match {
      case Admin => "admin"
      case Editor => "editor"
      case Viewer => "viewer"
    }

    // Check role hierarchy for escalation capability
    val canEscalate = configStore.get(s"security.roleHierarchy.$roleName.canEscalate")
    val level = configStore.get(s"security.roleHierarchy.$roleName.level")

    action match {
      case "admin.config.write" =>
        canEscalate.contains(true) && level.exists(_.asInstanceOf[Int] >= 100)
      case "content.edit" =>
        level.exists(_.asInstanceOf[Int] >= 50)
      case "content.view" =>
        level.exists(_.asInstanceOf[Int] >= 10)
      case _ => false
    }
  }
}

// Profile update handler - allows users to update their display preferences
class ProfileService(configStore: ConfigStore) {

  // Users can update their profile preferences stored in config
  // Path is restricted to user-specific namespace
  def updatePreference(user: User, key: String, value: Any): Either[String, Unit] = {
    // Validate key doesn't contain path traversal
    if (key.contains("..") || key.startsWith("/")) {
      return Left("Invalid preference key")
    }

    // Construct the preference path
    val basePath = s"users.${user.id}.preferences"
    val fullPath = s"$basePath.$key"

    // Additional validation: key must be alphanumeric segments separated by dots
    val segments = key.split("\\.")
    if (!segments.forall(s => s.nonEmpty && s.forall(c => c.isLetterOrDigit || c == '_'))) {
      return Left("Preference key must contain only alphanumeric characters and dots")
    }

    configStore.set(fullPath, value)
    Right(())
  }
}

// Bulk configuration import for admin operations
class ConfigImportService(configStore: ConfigStore, accessControl: AccessControl) {

  def importConfig(user: User, entries: Map[String, Any]): Either[String, Int] = {
    if (!accessControl.canPerformAction(user, "admin.config.write")) {
      return Left("Insufficient permissions")
    }

    var count = 0
    entries.foreach { case (path, value) =>
      configStore.set(path, value)
      count += 1
    }
    Right(count)
  }
}

// The vulnerability: theme customization endpoint that merges user input into config
class ThemeService(configStore: ConfigStore) {

  private val allowedThemeKeys = Set("color", "font", "layout", "density")

  def applyTheme(user: User, themeData: Map[String, Any]): Either[String, Unit] = {
    // Filter to only allowed theme keys at the top level
    val filtered = themeData.filter { case (k, _) => allowedThemeKeys.contains(k) }

    // Deep merge theme data into the config store
    filtered.foreach { case (key, value) =>
      deepMerge(s"themes.${user.id}.$key", value)
    }
    Right(())
  }

  // Recursively merge nested maps into the config store
  private def deepMerge(basePath: String, value: Any): Unit = {
    value match {
      case m: Map[String, Any] @unchecked =>
        m.foreach { case (k, v) =>
          deepMerge(s"$basePath.$k", v)
        }
      case other =>
        configStore.set(basePath, other)
    }
  }
}

